def _norm(s):
    return re.sub(r'[^a-z0-9]', '', (s or '').lower())


def _d(s):
    try:
        return datetime.strptime(s, "%Y-%m-%d").date() if s else None
    except (ValueError, TypeError):
        return None


def _dt(s):
    d = _d(s)
    return datetime(d.year, d.month, d.day) if d else None


def seed_maint_register() -> int:
    """Insert the historical register rows once, keyed by ref_no (idempotent).

    Matches each row's machine to an existing asset by normalized name/code;
    if none matches, creates a minimal asset so no history is lost. Safe to run
    on every startup — rows already present (by ref_no) are skipped.
    """
    db = SessionLocal()
    try:
        existing = {r[0] for r in db.query(MaintEvent.ref_no)
                    .filter(MaintEvent.ref_no.isnot(None)).all()}
        amap = {}
        used_codes = set()
        for a in db.query(MaintAsset).all():
            used_codes.add(a.asset_code)
            for key in (_norm(a.description), _norm(a.asset_code)):
                if key:
                    amap.setdefault(key, a.id)
        made = 0
        for row in SEED_ROWS:
            ref = (row.get("ref_no") or "").strip()
            if not ref or ref in existing:
                continue
            machine = row.get("machine") or ""
            aid = amap.get(_norm(machine))
            if not aid:
                base = ("IMP-" + _norm(machine))[:20] or "IMP"   # normalized -> keeps the number
                code, i = base, 2
                while code in used_codes:
                    sfx = f"-{i}"; code = base[:20 - len(sfx)] + sfx; i += 1
                used_codes.add(code)
                a = MaintAsset(asset_code=code, description=machine or "Imported")
                db.add(a); db.flush()
                aid = a.id
                amap[_norm(machine)] = aid
            db.add(MaintEvent(
                asset_id=aid, ref_no=ref,
                event_date=_d(row.get("event_date")) or datetime.utcnow().date(),
                category=row.get("category") or "Breakdown",
                status=row.get("status"),
                reported_at=_dt(row.get("reported_at")),
                restored_at=_dt(row.get("restored_at")),
                downtime_hrs=row.get("downtime_hrs"),
                complaint=row.get("complaint"), cause=row.get("cause"),
                action=row.get("action"), operator=row.get("operator"),
                repaired_by=row.get("repaired_by"), remarks=row.get("remarks"),
            ))
            existing.add(ref); made += 1
        db.commit()
        return made
    except Exception:
        db.rollback(); raise
    finally:
        db.close()
